contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address failingCallee, bytes memory failData, address okCallee, bytes memory okData) public payable {
        bool failReverted;
        c.forward(failingCallee, failData); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            failReverted = true;
        } else {
            failReverted = false;
        }

        bool okReverted;
        c.forward(okCallee, okData); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            okReverted = true;
        } else {
            okReverted = false;
        }

        uint256 balBefore = address(c).balance;
        c.forward(okCallee, okData); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        assert(okReverted == false && balAfter == balBefore);
    }

    receive() external payable {}
}

