pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(address failingCallee, bytes memory failData, address okCallee, bytes memory okData) internal {
        bool failReverted;
        try c.forward(failingCallee, failData) {
            failReverted = false;
        } catch {
            failReverted = true;
        }
        bool okReverted;
        try c.forward(okCallee, okData) {
            okReverted = false;
        } catch {
            okReverted = true;
        }
        uint256 balBefore = address(c).balance;
        try c.forward(okCallee, okData) {} catch { return; }
        uint256 balAfter = address(c).balance;
        assertTrue(okReverted == false && balAfter == balBefore);
    }

